<script setup>
import { computed,onMounted,ref,reactive } from 'vue'
import { UserPlus,RefreshCw,Pencil,KeyRound,Trash2 } from 'lucide-vue-next'
import { api } from '../api'
import { roleNames,identity } from '../auth'
import { CdcMessage,CdcMessageBox } from './ui/feedback'
const users=ref([]),query=ref(''),role=ref(''),loading=ref(false),dialog=ref(false),saving=ref(false),error=ref(''),reset=ref(null),newPassword=ref('')
const form=reactive({id:null,username:'',name:'',email:'',role:'VIEWER',enabled:true,password:''})
const visible=computed(()=>users.value.filter(u=>(!role.value||u.role===role.value)&&(!query.value||`${u.username} ${u.name} ${u.email}`.toLowerCase().includes(query.value.toLowerCase()))))
async function load(){loading.value=true;try{users.value=await api('/users');error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(user){Object.assign(form,{id:null,username:'',name:'',email:'',role:'VIEWER',enabled:true,password:''},user||{});error.value='';dialog.value=true}
async function save(){if(!String(form.username||'').trim()){error.value='请填写用户名';return}if(!String(form.name||'').trim()){error.value='请填写姓名';return}if(form.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)){error.value='邮箱格式不正确';return}if(!form.id&&String(form.password||'').length<8){error.value='初始密码至少 8 位';return}saving.value=true;error.value='';try{await api('/users'+(form.id?'/'+form.id:''),{method:form.id?'PUT':'POST',body:JSON.stringify(form)});dialog.value=false;CdcMessage.success('用户已保存');await load();if(form.id===identity.user?.id)window.dispatchEvent(new Event('cdc-session-expired'))}catch(e){error.value=e.message}finally{saving.value=false}}
async function action(user,name){try{await CdcMessageBox.confirm(`确定${{delete:'删除',enable:'启用',disable:'停用'}[name]}用户 ${user.username}？${name==='delete'?'用户名将不再可复用。':''}`,'用户操作');await api(name==='delete'?'/users/'+user.id:`/users/${user.id}/actions/${name}`,{method:name==='delete'?'DELETE':'POST'});await load();if(user.id===identity.user?.id)window.dispatchEvent(new Event('cdc-session-expired'))}catch(e){if(e instanceof Error)CdcMessage.error(e.message)}}
async function resetPassword(){saving.value=true;try{await api(`/users/${reset.value.id}/actions/reset-password`,{method:'POST',body:JSON.stringify({password:newPassword.value})});const self=reset.value.id===identity.user?.id;reset.value=null;newPassword.value='';CdcMessage.success('密码已重置，该用户会话已撤销');if(self)window.dispatchEvent(new Event('cdc-session-expired'))}catch(e){CdcMessage.error(e.message)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><div class="toolbar user-toolbar"><div class="search-box"><input v-model="query" placeholder="搜索用户名、姓名或邮箱" aria-label="搜索用户"/></div><cdc-select v-model="role" clearable placeholder="全部角色"><cdc-option v-for="(label,key) in roleNames" :key="key" :label="label" :value="key"/></cdc-select><span class="toolbar-spacer"/><cdc-button size="small" :loading="loading" @click="load"><RefreshCw :size="14"/>刷新</cdc-button><cdc-button type="primary" @click="edit()"><UserPlus :size="15"/>新建用户</cdc-button></div><div v-if="error&&!dialog" class="alert-bar error">{{error}}</div><div class="table-wrap"><table><thead><tr><th>用户</th><th>姓名</th><th>角色</th><th>邮箱</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="user in visible" :key="user.id"><td class="mono">{{user.username}}</td><td>{{user.name}}</td><td><span class="badge" :class="user.role==='ADMIN'?'status-snapshotting':user.role==='OPERATOR'?'badge-info':''">{{roleNames[user.role]}}</span></td><td>{{user.email||'—'}}</td><td><span class="badge" :class="user.enabled?'badge-success':'badge-warning'">{{user.enabled?'启用':'停用'}}</span></td><td class="mono">{{user.lastLoginAt?new Date(user.lastLoginAt).toLocaleString():'从未登录'}}</td><td><div class="row-actions"><cdc-button size="small" @click="edit(user)"><Pencil :size="14"/>编辑</cdc-button><cdc-button size="small" @click="newPassword='';reset=user"><KeyRound :size="14"/>重置密码</cdc-button><cdc-button size="small" @click="action(user,user.enabled?'disable':'enable')">{{user.enabled?'停用':'启用'}}</cdc-button><button class="icon-btn danger" title="删除用户" aria-label="删除用户" @click="action(user,'delete')"><Trash2 :size="14"/></button></div></td></tr><tr v-if="!visible.length"><td colspan="7" class="empty-state">{{loading?'正在加载…':'当前筛选下没有用户'}}</td></tr></tbody></table></div><cdc-modal v-model="dialog" :title="form.id?'编辑用户':'新建用户'"><div v-if="error" class="alert-bar error" role="alert">{{error}}</div><cdc-form><cdc-form-item label="用户名" required><cdc-input v-model="form.username" :disabled="!!form.id" autocomplete="off"/><div class="form-help">创建后不可修改</div></cdc-form-item><cdc-form-item label="姓名" required><cdc-input v-model="form.name"/></cdc-form-item><cdc-form-item label="邮箱"><cdc-input v-model="form.email" type="email"/></cdc-form-item><cdc-form-item label="角色"><cdc-select v-model="form.role"><cdc-option v-for="(label,key) in roleNames" :key="key" :label="label" :value="key"/></cdc-select></cdc-form-item><cdc-form-item v-if="!form.id" label="初始密码" required><cdc-input v-model="form.password" type="password" autocomplete="new-password"/><div class="form-help">至少 8 位，包含字母和数字</div></cdc-form-item><cdc-checkbox v-model="form.enabled">启用用户</cdc-checkbox></cdc-form><template #footer><cdc-button @click="dialog=false">取消</cdc-button><cdc-button type="primary" :loading="saving" @click="save">保存</cdc-button></template></cdc-modal><cdc-modal :model-value="!!reset" title="重置密码" @update:model-value="reset=null"><p class="dim">重置后会撤销该用户所有登录会话。</p><cdc-form-item label="新密码"><cdc-input v-model="newPassword" type="password" autocomplete="new-password"/><div class="form-help">至少 8 位，包含字母和数字</div></cdc-form-item><template #footer><cdc-button @click="reset=null">取消</cdc-button><cdc-button type="primary" :loading="saving" @click="resetPassword">确认重置</cdc-button></template></cdc-modal></div></template>
